slides=[]; media={}
def new(title,old=None):
    s=Slide(len(slides)+1,title); slides.append(s)
    if old:
        r=E.fromstring(original[f'ppt/notesSlides/notesSlide{old}.xml']); s.notes=' '.join(t.text or '' for t in r.findall('.//'+q(A,'t')))
    else: s.notes='Источник общей ER-схемы: night/image/mermaid-diagram-2026-11-14-203234.png. Оригинальное изображение целиком, без обрезки и без разделения на несколько слайдов. Модель логическая, не доказательство единых снимков или наличия всех полей в обработке.'
    return s
def picture(s,path,x,y,w,h):
    data=(ROOT/path).read_bytes(); iw,ih=struct.unpack('>II',data[16:24]); scale=min(w/iw,h/ih); ww,hh=iw*scale,ih*scale
    p=sub(s.tree,P,'pic'); nv=sub(p,P,'nvPicPr'); sub(nv,P,'cNvPr',{'id':str(s.next),'name':path}); s.next+=1; sub(nv,P,'cNvPicPr'); sub(nv,P,'nvPr'); rid=f'rIdImage{s.next}'; bf=sub(p,P,'blipFill'); sub(bf,A,'blip',{q(R,'embed'):rid}); sub(sub(bf,A,'stretch'),A,'fillRect'); sp=sub(p,P,'spPr'); xf(sp,x+(w-ww)/2,y+(h-hh)/2,ww,hh); sub(sub(sp,A,'prstGeom',{'prst':'rect'}),A,'avLst')
    name=f'plain_{s.num}_{s.next}.png'; media['ppt/media/'+name]=data; s.rels.append((rid,R+'/image','../media/'+name))
