# Preserve the image-version base but replace all its slides, excluding deleted appendices.
parts=original.copy()
for n in list(parts):
    if n.startswith('ppt/slides/') or n.startswith('ppt/notesSlides/'): del parts[n]
types=E.fromstring(parts['[Content_Types].xml'])
for e in list(types):
    if e.get('PartName','').startswith(('/ppt/slides/','/ppt/notesSlides/')): types.remove(e)
pres=E.fromstring(parts['ppt/presentation.xml']); ids=pres.find(q(P,'sldIdLst')); ids.clear(); pr=E.fromstring(parts['ppt/_rels/presentation.xml.rels'])
for e in list(pr):
    if e.get('Type','').endswith('/slide'): pr.remove(e)
for s in slides:
    # Red original logo and bottom folio, matching the image version.
    picture(s,'night/image/Alfa-Buduschee_01_krasny_1.png',842,25,88,34)
    for sh in s.root.findall('.//'+q(P,'sp')):
        if ''.join(t.text or '' for t in sh.findall('.//'+q(A,'t')))==f'{s.num:02}':
            tr=sh.find('./'+q(P,'spPr')+'/'+q(A,'xfrm')); tr.find(q(A,'off')).set('x',emu(934)); tr.find(q(A,'off')).set('y',emu(508)); tr.find(q(A,'ext')).set('cx',emu(22))
    rid=f'rIdSimple{s.num}'; sub(ids,P,'sldId',{'id':str(255+s.num),q(R,'id'):rid}); E.SubElement(pr,q(REL,'Relationship'),{'Id':rid,'Type':R+'/slide','Target':f'slides/slide{s.num}.xml'})
    parts[f'ppt/slides/slide{s.num}.xml']=xml(s.root); parts[f'ppt/slides/_rels/slide{s.num}.xml.rels']=relationships([('rIdLayout',R+'/slideLayout','../slideLayouts/slideLayout1.xml'),('rIdNotes',R+'/notesSlide',f'../notesSlides/notesSlide{s.num}.xml')]+s.rels)
    parts[f'ppt/notesSlides/notesSlide{s.num}.xml']=xml(notes(s.notes)); parts[f'ppt/notesSlides/_rels/notesSlide{s.num}.xml.rels']=relationships([('rIdSlide',R+'/slide',f'../slides/slide{s.num}.xml')])
    for part,typ in [('slides/slide','slide'),('notesSlides/notesSlide','notesSlide')]: E.SubElement(types,q(CT,'Override'),{'PartName':f'/ppt/{part}{s.num}.xml','ContentType':f'application/vnd.openxmlformats-officedocument.presentationml.{typ}+xml'})
# Remove orphan source images left behind by the old appendix.
for n in list(parts):
    if n.startswith('ppt/media/'): del parts[n]
parts.update(media); parts['ppt/presentation.xml']=xml(pres); E.register_namespace('',REL); parts['ppt/_rels/presentation.xml.rels']=xml(pr); E.register_namespace('',CT); parts['[Content_Types].xml']=xml(types)
out=NIGHT/'output/Dota2_All_Cases_v2_simple.pptx'
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
    for n,v in parts.items(): z.writestr(n,v)
(NIGHT/'qa/simple_manifest.json').write_text(json.dumps([{'slide':s.num,'title':s.title} for s in slides],ensure_ascii=False,indent=2),encoding='utf-8')
print(out)
